const list = ($input.first().json.report) || [];
const rows = list.map(p => {
  const dev = p.deviation_pct;
  const devStr = dev === null || dev === undefined ? '-' : (dev > 0 ? '+' + dev : dev) + '%';
  let badge = '<span style="background:#10b981;color:white;padding:2px 6px;border-radius:3px">OK</span>';
  if (dev !== null && dev !== undefined) {
    if (dev > 30) badge = '<span style="background:#dc2626;color:white;padding:2px 6px;border-radius:3px">CRITICO</span>';
    else if (dev > 10) badge = '<span style="background:#f59e0b;color:white;padding:2px 6px;border-radius:3px">DESVIO</span>';
  }
  const flags = [];
  if (p.pending_review > 0) flags.push(p.pending_review + ' por revisar');
  if (p.disputed > 0) flags.push(p.disputed + ' disputadas');
  if (p.low_confidence > 0) flags.push(p.low_confidence + ' baja confianza OCR');
  const flagsStr = flags.length ? '<small style="color:#dc2626">' + flags.join(' | ') + '</small>' : '-';
  const margin = Number(p.margin_now) || 0;
  const marginColor = margin >= 0 ? '#10b981' : '#dc2626';
  return '<tr>' +
    '<td>' + badge + '</td>' +
    '<td>' + (p.project_name || '?') + '</td>' +
    '<td>' + (p.estimated !== null ? Number(p.estimated).toLocaleString('es-ES') + 'eur' : '-') + '</td>' +
    '<td>' + Number(p.total_facturado).toLocaleString('es-ES') + 'eur</td>' +
    '<td>' + devStr + '</td>' +
    '<td>' + Number(p.total_certificado).toLocaleString('es-ES') + 'eur</td>' +
    '<td>' + Number(p.total_cobrado).toLocaleString('es-ES') + 'eur</td>' +
    '<td style="color:' + marginColor + ';font-weight:bold">' + margin.toLocaleString('es-ES') + 'eur</td>' +
    '<td>' + flagsStr + '</td>' +
    '</tr>';
}).join('');
const alerts = list.filter(p => (p.deviation_pct || 0) > 10).length;
const html = '<h2>Resumen financiero semanal</h2>' +
  '<p>Proyectos activos analizados: <b>' + list.length + '</b>. Con desviación &gt;10%: <b>' + alerts + '</b>.</p>' +
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">' +
  '<thead><tr style="background:#f3f4f6"><th>Estado</th><th>Proyecto</th><th>Estimado</th><th>Facturado</th><th>Desvío</th><th>Certificado</th><th>Cobrado</th><th>Margen actual</th><th>Alertas</th></tr></thead>' +
  '<tbody>' + rows + '</tbody></table>' +
  '<p style="font-size:12px;color:#6b7280">Margen actual = certificado - facturado (cliente paga lo certificado, tú pagas las facturas).</p>';
return [{ json: { html_body: html, count: list.length, alerts: alerts } }];

